model.format_error_template:
MCP call error: {{ error }}
Use bounded MCP resource reads to locate the issue. Use exactly one MCP
write or check call for a response.

model.observation_template:
{%- if output.output | length < 8000 -%}
{"returncode": {{ output.returncode }}, "output": {{ output.output | tojson }}{% if output.exception_info %}, "exception": {{ output.exception_info | tojson }}{% endif %}}
{%- else -%}
{"returncode": {{ output.returncode }}, "output_head": {{ output.output[:4000] | tojson }}, "output_tail": {{ output.output[-4000:] | tojson }}, "elided_chars": {{ output.output | length - 8000 }}}
{%- endif %}
